from itertools import permutations

def all_interval_series(size, fixed_values=None):
    if fixed_values is None:
        fixed_values = {}
    for p in permutations(range(size)):
        if all(p[i] == fixed_values.get(i) for i in range(size) if i in fixed_values):
            diffs = [abs(p[i] - p[i-1]) for i in range(1, size)]
            if sorted(diffs) == list(range(1, size)):
                return p
    return "UNSATISFIABLE"

print(all_interval_series(14, {6: 3, 12: 6}))
